//! 🧿 Remodeling mutation — `CreateGcp`: brings a new id-keyed ground control point into existence
//! (id pre-generated by the caller via `next_remodeling_id("gcp")`).

use crate::artifacts::remodeling::{GroundControlPoint, RemodelingSnapshot};
use crate::artifacts::remodeling::diff::{RemodelingDiff, RemodelingGcpList};
use crate::artifacts::remodeling::mutations::RemodelingMutation;
use serde::{Deserialize, Serialize};
use semio_framework_value_derive::{FromValue, ToValue};

//#region 🔖️Mutation
/// 🧿 `create-gcp` payload.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, ToValue, FromValue, dsl::DslRecord, dsl::MutationLeaf)]
#[mutation_leaf(contract = ::protocol)]
#[value(rename_all = "camelCase")]
#[serde(rename_all = "camelCase")]
#[dsl(keyword = "create-gcp")]
pub struct CreateGcp {
    #[dsl(block)]
    pub gcp: GroundControlPoint,
}

/// 🏗️ Builder — wraps the payload in its dispatch variant.
pub fn create_gcp(gcp: GroundControlPoint) -> RemodelingMutation {
    RemodelingMutation::CreateGcp(CreateGcp { gcp })
}

impl protocol::MutationKind<RemodelingSnapshot, RemodelingMutation> for CreateGcp {
    const SEMANTICS: protocol::SemanticDescriptor = protocol::SemanticDescriptor { verb: "create", entity: "gcp", kind: "create-gcp", record: "CreatedGcp" };

    async fn diff(&self, base: &RemodelingSnapshot) -> protocol::MutationOutcome<RemodelingDiff> {
        super::diff::diff(self, base)
    }
    async fn inverse(&self, base: &RemodelingSnapshot) -> Vec<RemodelingMutation> {
        super::inverse::inverse(self, base)
    }
    async fn label(&self) -> String {
        format!("Create GCP \"{}\"", self.gcp.id)
    }
    async fn target(&self) -> Vec<String> {
        vec![self.gcp.id.clone()]
    }
}
//#endregion 🔖️Mutation
